import { useEffect, useRef, useState } from 'react'
import type { ReactNode } from 'react'

import { LEGEND_INSET_PX } from '@jbrowse/bandage-core/labelLayout'
import { ErrorBanner, LoadingOverlay } from '@jbrowse/core/ui'
import { isAlive } from '@jbrowse/mobx-state-tree'
import { useRenderingBackend } from '@jbrowse/render-core/useRenderingBackend'
import { observer } from 'mobx-react'

import BubbleHalos from './BubbleHalos'
import EdgeMarksOverlay from './EdgeMarksOverlay'
import FacetPanels from './FacetPanels'
import GenePins from './GenePins'
import GraphToolbar from './GraphToolbar'
import HaplotypeSwitch from './HaplotypeSwitch'
import HoverLayer from './HoverLayer'
import HoverTooltip from './HoverTooltip'
import { DIMMED_OPACITY } from './LabelChip'
import LabelLayer from './LabelLayer'
import LayoutSwitch from './LayoutSwitch'
import { LegendPanel } from './Legend'
import PaneContextMenu from './PaneContextMenu'
import PassBars from './PassBars'
import ReferenceStripOverlay from './ReferenceStripOverlay'
import TubeMapOverlay from './TubeMapOverlay'
import WalkRowsOverlay from './WalkRowsOverlay'
import WalkStrip from './WalkStrip'
import WalkStripLocator from './WalkStripLocator'
import { usePaneGestures, useWheelZoom } from './usePaneGestures'
import { drawnLegendSections, legendSections } from '../legendSections'
import { PAPER_CSS } from '../pane/paneBase'
import { createGraphRenderer } from '../renderer/GraphRenderer'

import type { GraphPaneModel } from '../model'
import type { CanvasHandle } from '@jbrowse/display-kit/DisplayChromeBase'

const wrapperStyle = { position: 'relative' as const }

// The overlay origin has to be the canvas, not the wrapper: the wrapper also
// holds the toolbar, so anything positioned against it is offset by the
// toolbar's height, and a row label lands a whole row off the row it names.
const canvasAreaStyle = {
  position: 'relative' as const,
  lineHeight: 0,
  isolation: 'isolate' as const,
}

// Under a transparent canvas, from below the reference strip down, so the
// linear view's gridlines show only behind the strip
const paperStyle = {
  position: 'absolute' as const,
  left: 0,
  right: 0,
  bottom: 0,
  zIndex: 0,
}

// Above the labels, pins and legends drawn over the canvas, and with the line
// height the canvas area zeroes, which would collapse the overlay's label
const loadingLayerStyle = {
  position: 'absolute' as const,
  inset: 0,
  zIndex: 10,
  lineHeight: 'normal',
  pointerEvents: 'none' as const,
}

const rowLabelStyle = {
  position: 'absolute' as const,
  left: 6,
  transform: 'translateY(-50%)',
  background: 'rgba(255,255,255,0.82)',
  padding: '0 4px',
  borderRadius: 3,
  fontSize: 11,
  // explicit, because the canvas container zeroes line-height to kill the
  // inline-block gap under the canvas. Inherited, that collapses the label to a
  // zero-height box: it still paints, but it has no layout, so anything asking
  // whether it is visible (a screenshot spec's waitForVisible, a11y tooling)
  // is told no.
  lineHeight: '16px',
  whiteSpace: 'nowrap' as const,
  pointerEvents: 'none' as const,
  zIndex: 4,
}

// Names the rows of a row-structured layout (anchored, sample rows). Without
// them the layout draws real structure that cannot be read: a stack of bars
// where every row means something and nothing says what.
//
// Positioned from the layout's own `rowLabels` through the same transform the
// canvas draws with, so a label tracks its row across pan and zoom instead of
// sitting at a measured pixel. It therefore has to be mounted in the canvas's
// own positioning context (canvasAreaStyle) — against the wrapper it picks up
// the toolbar's height and names the wrong row. Pinned to the left edge rather
// than to the row's own x, because a row's leftmost node is wherever its first
// allele happens to branch.
//
// Keyed on the row, not on the label: two rows can have the same words. The
// sample-row layout names row 0 for the assembly the backbone comes from and
// the rows below it for the samples contributing alleles, and a diploid
// reference is in both lists — one haplotype is the reference path, the other
// walks alleles of its own, and `parsePanSN` reduces both to one sample name.
const RowLabels = observer(function RowLabels({
  model,
}: {
  model: GraphPaneModel
}) {
  return (
    <>
      {model.visibleRowLabels.map(({ label, y, top }) => (
        <div
          key={y}
          data-testid="graph-row-label"
          style={{ ...rowLabelStyle, top }}
        >
          {label}
        </div>
      ))}
    </>
  )
})

// Top right, in the column the fit leaves it (keyColumnPx). Every key
// stretches to the widest, so together they read as one panel. It takes the pointer, for its rows'
// titles and its close button.
const legendStackStyle = {
  position: 'absolute' as const,
  display: 'flex',
  flexDirection: 'column' as const,
  borderRadius: 3,
  overflowX: 'hidden' as const,
  overflowY: 'auto' as const,
  zIndex: 4,
}

const nodeLabelStyle = {
  position: 'absolute' as const,
  transform: 'translate(-50%, -50%)',
  background: 'rgba(255,255,255,0.78)',
  padding: '0 3px',
  borderRadius: 3,
  fontSize: 10,
  lineHeight: '13px',
  whiteSpace: 'nowrap' as const,
  pointerEvents: 'none' as const,
  zIndex: 3,
}

// Measures itself for the model, so no label is placed under a legend and
// none gives way to one that is not drawn.
//
// At rest only, and again on returning to rest: a hover's walk keys would
// otherwise refit the view, and the refit clears the hover that grew them
//
// `children` head the column, over the key, and are measured with it
export const Legends = observer(function Legends({
  model,
  children,
}: {
  model: GraphPaneModel
  children?: ReactNode
}) {
  const ref = useRef<HTMLDivElement>(null)
  const atRest = model.legendAtRest
  // what the key draws, which the model derives as the drawing changes, so
  // the labels wait for its measure; the panel draws in the same render, so
  // the measure after it is of that key
  const shape = model.keyShape
  useEffect(() => {
    model.setKeyShapeOf(() => JSON.stringify(legendSections(model)))
  }, [model])
  useEffect(() => {
    const el = ref.current
    if (!el || !atRest) {
      return
    }
    // the last callback can land after the track is closed. scrollHeight is
    // the whole key, even where the pane caps it to scroll, so the pane
    // still grows to show it all when it can. The key mounts once it has
    // sections, which can be after this, so each measure observes what the
    // column holds.
    const resizes = new ResizeObserver(() => {
      measure()
    })
    const measure = () => {
      for (const child of el.children) {
        resizes.observe(child)
      }
      if (isAlive(model) && model.legendAtRest) {
        model.setLegendSize(
          { width: el.offsetWidth, height: el.scrollHeight },
          shape,
        )
      }
    }
    resizes.observe(el)
    measure()
    return () => {
      resizes.disconnect()
    }
  }, [model, atRest, shape])
  return (
    <div
      ref={ref}
      style={{
        ...legendStackStyle,
        top: LEGEND_INSET_PX + model.referenceStripZonePx,
        right: LEGEND_INSET_PX,
        maxHeight:
          model.canvasHeight - 2 * LEGEND_INSET_PX - model.referenceStripZonePx,
      }}
    >
      {children}
      <LegendPanel model={model} sections={drawnLegendSections(model)} />
    </div>
  )
})

// Writes each node's length onto it, which is what Bandage's Length label does.
// graphLabels applies the same transform the canvas draws with, so a label
// tracks its node across pan and zoom, and decides which labels fit; this only
// paints them, mounted in the canvas's own positioning context for the reason
// RowLabels is.
export const GraphSizeLabels = observer(function GraphSizeLabels({
  model,
}: {
  model: GraphPaneModel
}) {
  return (
    <>
      {model.overlayLabels.sizes.map(({ key, node, text, x, y }) => (
        <div
          key={key}
          data-testid="graph-size-label"
          style={{
            ...nodeLabelStyle,
            left: x,
            top: y,
            opacity: model.nodeFaded(node) ? DIMMED_OPACITY : undefined,
          }}
        >
          {text}
        </div>
      ))}
    </>
  )
})

type PaneCanvas = Pick<CanvasHandle, 'canvasRef' | 'canvas'>

interface OwnChrome {
  renderError: unknown
  retryRender: () => void
}

// `ownChrome` absent for a pane inside a track, whose controls, loading
// state and errors are the track's `DisplayChrome`. A hosted pane whose x the
// host places takes no pan or wheel of its own: those are the linear view's,
// as on any other track. One drawing its own coordinates inside a track keeps
// them, and keeps them from the view.
const GraphCanvasBody = observer(function GraphCanvasBody({
  model,
  handle: { canvasRef, canvas },
  ownChrome,
}: {
  model: GraphPaneModel
  handle: PaneCanvas
  ownChrome?: OwnChrome
}) {
  const {
    handlers,
    canvasStyle,
    surfaceProps,
    labelHandlers,
    contextMenu,
    closeContextMenu,
    hoveredChip,
  } = usePaneGestures(model)
  const [area, setArea] = useState<HTMLDivElement | null>(null)
  useWheelZoom(area, canvas, model)
  const faceted = model.facetPanels !== undefined

  return (
    <div style={wrapperStyle} {...surfaceProps}>
      {ownChrome ? <GraphToolbar model={model} /> : null}

      <div
        ref={setArea}
        style={canvasAreaStyle}
        {...labelHandlers}
        onMouseEnter={() => {
          model.setPointerInPane(true)
        }}
        onMouseLeave={() => {
          if (isAlive(model)) {
            model.setPointerInPane(false)
          }
        }}
      >
        {model.referenceStripShown ? (
          <div
            style={{
              ...paperStyle,
              top: model.referenceStripZonePx,
              background: PAPER_CSS,
            }}
          />
        ) : null}
        <canvas
          ref={canvasRef}
          data-testid="graph-genome-canvas"
          style={{
            ...canvasStyle,
            width: model.paneWidth,
            height: model.canvasHeight,
            clipPath: model.drawingClip,
            display: 'block',
            position: 'relative',
            zIndex: 1,
          }}
          {...handlers}
        />

        {faceted ? (
          <FacetPanels
            model={model}
            handlers={handlers}
            canvasStyle={canvasStyle}
            controls={
              ownChrome ? null : (
                <>
                  <LayoutSwitch model={model} inline />
                  <HaplotypeSwitch model={model} inline />
                </>
              )
            }
          />
        ) : (
          <>
            <TubeMapOverlay model={model} />
            <HoverLayer model={model} />
            <ReferenceStripOverlay model={model} />
            <EdgeMarksOverlay model={model} />
            <RowLabels model={model} />
            <GraphSizeLabels model={model} />
            <BubbleHalos model={model} />
            <GenePins model={model} />
            <LabelLayer model={model} />
            <WalkRowsOverlay model={model} />
            <WalkStripLocator model={model} />
            <Legends model={model}>
              {ownChrome ? null : (
                <>
                  <LayoutSwitch model={model} />
                  <HaplotypeSwitch model={model} />
                </>
              )}
            </Legends>
          </>
        )}

        {ownChrome ? (
          <div style={loadingLayerStyle}>
            <LoadingOverlay
              isVisible={model.isLoading}
              immediate={!model.layoutResult}
              statusMessage={model.statusMessage}
              onCancel={
                model.canCancelLoad
                  ? () => {
                      model.cancelLoad()
                    }
                  : undefined
              }
            />
          </div>
        ) : null}

        <HoverTooltip model={model} chip={hoveredChip} />
      </div>

      <PassBars model={model} />

      {model.walkStripShown ? <WalkStrip model={model} /> : null}

      <PaneContextMenu
        model={model}
        at={contextMenu}
        onClose={closeContextMenu}
      />

      {ownChrome?.renderError ? (
        <ErrorBanner
          error={ownChrome.renderError}
          onReset={ownChrome.retryRender}
        />
      ) : null}

      {ownChrome && model.error ? (
        <ErrorBanner
          error={model.error}
          onReset={
            model.canRetryLoad
              ? () => {
                  model.retryLoad()
                }
              : undefined
          }
        />
      ) : null}
    </div>
  )
})

const StandaloneGraphCanvas = observer(function StandaloneGraphCanvas({
  model,
}: {
  model: GraphPaneModel
}) {
  const { canvasRef, canvas, error, retry } = useRenderingBackend(
    createGraphRenderer,
    model,
  )
  return (
    <GraphCanvasBody
      model={model}
      handle={{ canvasRef, canvas }}
      ownChrome={{ renderError: error, retryRender: retry }}
    />
  )
})

const GraphCanvas = observer(function GraphCanvas({
  model,
  handle,
}: {
  model: GraphPaneModel
  handle?: PaneCanvas
}) {
  return handle ? (
    <GraphCanvasBody model={model} handle={handle} />
  ) : (
    <StandaloneGraphCanvas model={model} />
  )
})

export default GraphCanvas
