import { useMemo, useState } from 'react'

import {
  walkRowReadoutAt,
  walkRowsKey,
  walkRowsTree,
} from '@jbrowse/bandage-core/layout/walkRowDraw'
import {
  stripGeneGaps,
  stripRowAt,
  walkMarksTree,
  walkStripLabelsTree,
} from '@jbrowse/bandage-core/layout/walkStrip'
import { RAMP_GRADIENT_CSS } from '@jbrowse/bandage-core/referenceRampCss'
import { isAlive } from '@jbrowse/mobx-state-tree'
import { observer } from 'mobx-react'

import ElTree, { useSvgId } from './ElTree'
import { LegendSwatchView } from './LegendSwatch'
import PaneContextMenu from './PaneContextMenu'
import { legendRowStyle } from './legendStyles'
import { walkRowSwatch } from '../legendSections'

import type { GraphPaneModel } from '../model'
import type { RowInk } from '@jbrowse/bandage-core/layout/rowInks'
import type { RowGene } from '@jbrowse/bandage-core/layout/walkRowDraw'
import type { WalkRows } from '@jbrowse/bandage-core/layout/walkRows'
import type { StripFrame } from '@jbrowse/bandage-core/layout/walkStrip'

// Walk rows under a layout that draws nodes, each haplotype's walk on its own
// bp, linked to the drawing above: the hovered node ticks every bar where its
// walk passes it, and a point on a bar lights its node, ringed, above. The
// bars share the drawing's colours, so under the reference-position ramp a hue
// in the drawing is the same hue on each bar, and a lifted walk's row takes
// its thread's colours. Every row is shown; rows too thin to letter say who
// they are on hover.

const keyStyle = {
  display: 'flex',
  flexWrap: 'wrap' as const,
  gap: '2px 14px',
  padding: '2px 8px 6px',
  fontSize: 11,
  color: '#333',
}

const tipStyle = {
  position: 'absolute' as const,
  pointerEvents: 'none' as const,
  background: 'rgba(255,255,255,0.92)',
  border: '1px solid #ccc',
  borderRadius: 3,
  padding: '1px 6px',
  fontSize: 11,
  whiteSpace: 'nowrap' as const,
  zIndex: 4,
}

// The bars, built once per rows, frame, colouring and genes rather than per
// hover
const StripBars = observer(function StripBars({
  bars,
  frame,
  ramp,
  rowGenes,
  inks,
}: {
  bars: WalkRows
  frame: StripFrame
  ramp: { start: number; end: number } | undefined
  rowGenes: Map<string, RowGene[]> | undefined
  inks: RowInk[]
}) {
  const idPrefix = useSvgId()
  const tree = useMemo(
    () =>
      walkRowsTree(bars, frame, {
        ramp,
        rowGenes,
        idPrefix,
        markUnloaded: true,
        inks,
      }),
    [bars, frame, ramp, rowGenes, idPrefix, inks],
  )
  return <ElTree el={tree} />
})

// The hovered row's readout in full where the rows are too thin to letter, or
// where its own readout is drawn cut, at the pointer's place on its bar. Its
// own observer, so a move along a bar redraws the tip and not the strip.
export const StripTip = observer(function StripTip({
  model,
}: {
  model: GraphPaneModel
}) {
  const bars = model.walkStripRows
  const frame = model.walkStripFrame
  const hover = model.stripHover
  const all = bars ? [bars.reference, ...bars.rows] : []
  const index = hover ? all.findIndex(r => r.name === hover.row) : -1
  const row = all[index]
  const at =
    bars && frame && row ? walkRowReadoutAt(bars, index, frame) : undefined
  if (!bars || !frame || !hover || !row || !at || (frame.labelled && !at.cut)) {
    return null
  }
  const x = (bars.origin + hover.offset) * frame.scaleX + frame.translateX
  // past the middle it opens leftward, so a long readout stays in the pane
  const side =
    x > frame.width / 2 ? { right: frame.width - x + 12 } : { left: x + 12 }
  return (
    <div
      data-testid="graph-walk-strip-tip"
      style={{
        ...tipStyle,
        ...side,
        top: index * frame.rowPx + frame.translateY - 18,
      }}
    >
      {row.label} · {at.text}
    </div>
  )
})

// Its own observer, so the node a hover lights redraws the ticks and not the
// strip
const StripMarks = observer(function StripMarks({
  model,
  bars,
  frame,
}: {
  model: GraphPaneModel
  bars: WalkRows
  frame: StripFrame
}) {
  return <ElTree el={walkMarksTree(bars, frame, model.walkStripMarks)} />
})

const WalkStrip = observer(function WalkStrip({
  model,
}: {
  model: GraphPaneModel
}) {
  const bars = model.walkStripRows
  const frame = model.walkStripFrame
  const [menu, setMenu] = useState<{
    clientX: number
    clientY: number
    row: number
  }>()
  if (!bars || !frame) {
    return null
  }
  const hit = (e: React.MouseEvent<SVGSVGElement>) => {
    const box = e.currentTarget.getBoundingClientRect()
    return stripRowAt(bars, frame, e.clientX - box.left, e.clientY - box.top)
  }
  const key = walkRowsKey(bars, {
    ramp: model.referenceRampDomain,
    rampCss: RAMP_GRADIENT_CSS,
    genes: stripGeneGaps(frame, model.walkRowGenes, model.walkRowGeneGaps),
    annotation: model.walkRowAnnotation,
    markUnloaded: true,
    inks: model.walkStripInks,
  })
  return (
    <div
      data-testid="graph-walk-strip"
      style={{ position: 'relative', borderTop: '1px solid #ddd' }}
      onMouseEnter={() => {
        model.setPointerInPane(true)
      }}
      onMouseLeave={() => {
        if (isAlive(model)) {
          model.setPointerInPane(false)
          model.setStripHover(null)
        }
      }}
    >
      <svg
        width={frame.width}
        height={frame.height}
        style={{ display: 'block' }}
        onMouseLeave={() => {
          if (isAlive(model)) {
            model.setStripHover(null)
          }
        }}
        onMouseMove={e => {
          const at = hit(e)
          e.currentTarget.style.cursor = at && at.index > 0 ? 'pointer' : ''
          model.setStripHover(
            at ? { row: at.row.name, offset: at.offset } : null,
          )
        }}
        onClick={e => {
          const at = hit(e)
          if (at && at.index > 0) {
            model.toggleWalk(at.row.name)
          }
        }}
        onContextMenu={e => {
          const at = hit(e)
          if (at) {
            e.preventDefault()
            setMenu({ clientX: e.clientX, clientY: e.clientY, row: at.index })
          }
        }}
      >
        <StripBars
          bars={bars}
          frame={frame}
          ramp={model.referenceRampDomain}
          rowGenes={model.walkRowGenes}
          inks={model.walkStripInks}
        />
        <StripMarks model={model} bars={bars} frame={frame} />
        <ElTree
          el={walkStripLabelsTree(
            bars,
            frame,
            new Set(model.walkLayers.map(l => l.walk)),
          )}
        />
      </svg>
      <StripTip model={model} />
      <div style={keyStyle} data-testid="graph-walk-strip-key">
        {key.map(entry => (
          <div key={entry.label} style={legendRowStyle}>
            <LegendSwatchView swatch={walkRowSwatch(entry.swatch)} />
            <span>{entry.label}</span>
          </div>
        ))}
        <span style={{ color: '#777' }}>
          Ticks mark where each walk passes the node under the pointer; click a
          haplotype&apos;s bar to lift its walk
        </span>
      </div>
      <PaneContextMenu
        model={model}
        at={menu && { ...menu, bars }}
        onClose={() => {
          setMenu(undefined)
        }}
      />
    </div>
  )
})

export default WalkStrip
